INSERT INTO `skill_type` (`ID`, `Name`, `Description`, `Parent`, `Group`, `PrimaryStat`, `SecondaryStat`, `MasterMessageID`, `GMMessageID`) VALUES (81, 'Mining', '', NULL, 1, 'Str', 'Con', 5386, 5387), (82, 'Forestry', '', NULL, 1, 'Str', 'Agi', 5394, 5395), (85, 'Hunting & Fishing', '', NULL, 1, 'Agi', 'Will', 5418, 5419), (87, 'Cooking & Household', '', NULL, 1, 'Int', 'Will', 5434, 5435), (88, 'Gathering', '', NULL, 1, 'Agi', 'Will', 5442, 5443), (83, 'Carpentry', '', 82, 1, 'Agi', 'Int', 5402, 5403), (84, 'Animal Husbandry', '', 85, 1, 'Will', 'Con', 5410, 5411), (86, 'Tailoring', '', 87, 1, 'Agi', 'Int', 5426, 5427) ON DUPLICATE KEY UPDATE `Name` = VALUES(`Name`), `Parent` = VALUES(`Parent`), `Group` = VALUES(`Group`), `PrimaryStat` = VALUES(`PrimaryStat`), `SecondaryStat` = VALUES(`SecondaryStat`), `MasterMessageID` = VALUES(`MasterMessageID`), `GMMessageID` = VALUES(`GMMessageID`);
INSERT INTO `skills` (`CharacterID`, `SkillTypeID`, `SkillAmount`, `LockStatus`) SELECT c.`ID`, n.`id`, IFNULL((SELECT MAX(k.`SkillAmount`) FROM `skills` k WHERE k.`CharacterID` = c.`ID` AND k.`SkillTypeID` = n.`src`), 0), 1 FROM `character` c JOIN (SELECT 81 AS `id`, 1 AS `src` UNION ALL SELECT 82 AS `id`, 6 AS `src` UNION ALL SELECT 83 AS `id`, 6 AS `src` UNION ALL SELECT 84 AS `id`, 2 AS `src` UNION ALL SELECT 85 AS `id`, 2 AS `src` UNION ALL SELECT 86 AS `id`, 2 AS `src` UNION ALL SELECT 87 AS `id`, 2 AS `src` UNION ALL SELECT 88 AS `id`, 2 AS `src`) n WHERE NOT EXISTS (SELECT 1 FROM `skills` s WHERE s.`CharacterID` = c.`ID` AND s.`SkillTypeID` = n.`id`);
