INSERT INTO `character_effects` (`PlayerEffectID`, `CharacterID`, `Magnitude`, `DurationLeft`) SELECT m.`eff`, s.`CharacterID`, 10000000, 315360000 FROM `skills` s JOIN `character` c ON c.`ID` = s.`CharacterID` JOIN (SELECT 1 AS `sk`, 125 AS `eff` UNION ALL SELECT 2 AS `sk`, 126 AS `eff` UNION ALL SELECT 3 AS `sk`, 127 AS `eff` UNION ALL SELECT 4 AS `sk`, 128 AS `eff` UNION ALL SELECT 5 AS `sk`, 129 AS `eff` UNION ALL SELECT 6 AS `sk`, 130 AS `eff` UNION ALL SELECT 7 AS `sk`, 131 AS `eff` UNION ALL SELECT 10 AS `sk`, 132 AS `eff` UNION ALL SELECT 11 AS `sk`, 133 AS `eff` UNION ALL SELECT 12 AS `sk`, 134 AS `eff` UNION ALL SELECT 13 AS `sk`, 135 AS `eff` UNION ALL SELECT 14 AS `sk`, 136 AS `eff` UNION ALL SELECT 15 AS `sk`, 137 AS `eff` UNION ALL SELECT 16 AS `sk`, 138 AS `eff` UNION ALL SELECT 17 AS `sk`, 139 AS `eff` UNION ALL SELECT 18 AS `sk`, 140 AS `eff` UNION ALL SELECT 19 AS `sk`, 141 AS `eff` UNION ALL SELECT 20 AS `sk`, 142 AS `eff` UNION ALL SELECT 21 AS `sk`, 143 AS `eff` UNION ALL SELECT 22 AS `sk`, 144 AS `eff` UNION ALL SELECT 23 AS `sk`, 145 AS `eff` UNION ALL SELECT 24 AS `sk`, 146 AS `eff` UNION ALL SELECT 25 AS `sk`, 147 AS `eff` UNION ALL SELECT 26 AS `sk`, 148 AS `eff` UNION ALL SELECT 27 AS `sk`, 149 AS `eff` UNION ALL SELECT 81 AS `sk`, 150 AS `eff` UNION ALL SELECT 82 AS `sk`, 151 AS `eff` UNION ALL SELECT 83 AS `sk`, 152 AS `eff` UNION ALL SELECT 84 AS `sk`, 153 AS `eff` UNION ALL SELECT 85 AS `sk`, 154 AS `eff` UNION ALL SELECT 86 AS `sk`, 155 AS `eff` UNION ALL SELECT 87 AS `sk`, 156 AS `eff` UNION ALL SELECT 88 AS `sk`, 157 AS `eff`) m ON m.`sk` = s.`SkillTypeID` WHERE s.`SkillAmount` >= 1000000000 GROUP BY m.`eff`, s.`CharacterID`;
