-- ----------------------------------------------------------------------------
-- Steam Hammer mod: Acribian character creation (sh_client.exe unchanged).
-- The client mod pack sends an Acribian as Fraction 1 + Race 2 (race selection
-- is disabled in SH, players are always Race 1); this turns it into an
-- Acribian (Fraction 2, Race 1, RaceID 1) as the character is inserted.
-- Re-created at every server start. Single statement (no BEGIN/END needed).
-- ----------------------------------------------------------------------------
DROP TRIGGER IF EXISTS `sh_acribian_on_create`;
CREATE TRIGGER `sh_acribian_on_create` BEFORE INSERT ON `character` FOR EACH ROW SET NEW.`RaceID` = IF(NEW.`Fraction` = 1 AND NEW.`Race` = 2, 1, NEW.`RaceID`), NEW.`Fraction` = IF(NEW.`Fraction` = 1 AND NEW.`Race` = 2, 2, NEW.`Fraction`), NEW.`Race` = IF(NEW.`Fraction` = 2 AND NEW.`Race` = 2, 1, NEW.`Race`);

